import { access } from "node:fs/promises";
import { join } from "node:path";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { withFileMutationQueue } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import {
  captureSession,
  diffSources,
  fetchOKFSpec,
  formatCaptureReport,
  formatDiffReport,
  formatInspectionReport,
  formatSpecReport,
  formatValidationReport,
  initializeBundle,
  inspectProject,
  resolveFromCwd,
  summarizeInit,
  validateBundle,
} from "./core.ts";

const OKF_PROMPT_PATTERN = /(?:\bOKF\b|open knowledge format|\bokf\/)/i;
const SKILL_BACKED_COMMANDS = {
  "okf-init": "Run the /okf-init workflow.",
  "okf-update": "Run the /okf-update workflow.",
  "okf-upgrade": "Run the /okf-upgrade workflow.",
  "okf-compact": "Run the /okf-compact workflow.",
} as const;

export default function okfExtension(pi: ExtensionAPI): void {
  pi.registerCommand("okf-validate", {
    description: "Validate an OKF v0.2 bundle (legacy v0.1 metadata tolerated with migration warnings)",
    handler: async (args, ctx) => {
      const path = firstArgument(args) ?? "okf";
      const report = await validateBundle(resolveFromCwd(ctx.cwd, path));
      ctx.ui.notify(formatValidationReport(report), report.valid ? "info" : "error");
    },
  });

  pi.registerCommand("okf-inspect", {
    description: "List likely product, schema, analytics, and dashboard source files",
    handler: async (args, ctx) => {
      const sourcePath = resolveFromCwd(ctx.cwd, firstArgument(args) ?? ".");
      const report = await inspectProject(sourcePath);
      ctx.ui.notify(formatInspectionReport(report), "info");
    },
  });

  pi.on("input", (event) => {
    const match = event.text.match(/^\/(okf-init|okf-update|okf-upgrade|okf-compact)(?:\s+([\s\S]*))?$/);
    if (!match) return { action: "continue" };

    const command = match[1] as keyof typeof SKILL_BACKED_COMMANDS;
    const args = match[2]?.trim();
    const instruction = args
      ? `${SKILL_BACKED_COMMANDS[command]}\nArguments: ${args}`
      : SKILL_BACKED_COMMANDS[command];

    return {
      action: "transform",
      text: `/skill:okf ${instruction}`,
      images: event.images,
    };
  });

  pi.registerTool({
    name: "okf_spec",
    label: "Fetch OKF Specification",
    description:
      "Fetch the authoritative current Open Knowledge Format specification from GoogleCloudPlatform/knowledge-catalog.",
    promptSnippet: "Fetch the current OKF specification before authoring or upgrading a bundle",
    promptGuidelines: [
      "Use okf_spec before /okf-init, /okf-upgrade, or when unsure of current frontmatter conventions. Do not rely on model memory of the spec.",
    ],
    parameters: Type.Object({}),
    async execute() {
      const spec = await fetchOKFSpec();
      return {
        content: [{ type: "text", text: formatSpecReport(spec) }],
        details: { version: spec.version, url: spec.url },
      };
    },
  });

  pi.registerTool({
    name: "okf_inspect",
    label: "Inspect OKF Sources",
    description:
      "Read-only inventory of likely product docs, schemas, analytics, and dashboard sources before authoring an OKF bundle.",
    promptSnippet: "Inspect likely project knowledge sources before authoring an OKF bundle",
    promptGuidelines: [
      "Use okf_inspect before authoring or updating an OKF bundle, then verify facts from the reported source files rather than inventing content.",
    ],
    parameters: Type.Object({
      path: Type.Optional(
        Type.String({ description: "Project directory to inspect, relative to the current working directory." }),
      ),
      maxFiles: Type.Optional(
        Type.Integer({ minimum: 1, maximum: 5000, description: "Maximum files to scan; defaults to 500." }),
      ),
    }),
    async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
      const report = await inspectProject(resolveFromCwd(ctx.cwd, params.path ?? "."), params.maxFiles ?? 500);
      return { content: [{ type: "text", text: formatInspectionReport(report) }], details: report };
    },
  });

  pi.registerTool({
    name: "okf_diff",
    label: "Git Diff Changed Sources",
    description:
      "List files changed since a git ref (default HEAD) so OKF bundle authoring can be scoped to uncommitted work.",
    promptSnippet: "List changed files relative to a git ref",
    promptGuidelines: [
      "Use okf_diff when /okf-update diff runs, or to scope an OKF authoring pass to recently changed files. Pass base='origin/main' (or another ref) for a wider window.",
    ],
    parameters: Type.Object({
      base: Type.Optional(
        Type.String({
          description:
            "Git ref to diff against. Defaults to HEAD (uncommitted changes). Use origin/main, a SHA, or a tag for a wider window.",
        }),
      ),
      path: Type.Optional(
        Type.String({ description: "Subdirectory to scope the diff to, relative to the current working directory." }),
      ),
      includeUntracked: Type.Optional(
        Type.Boolean({ description: "Include files not yet tracked by git. Defaults to true." }),
      ),
    }),
    async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
      const report = await diffSources(ctx.cwd, {
        base: params.base,
        path: params.path,
        includeUntracked: params.includeUntracked,
      });
      return { content: [{ type: "text", text: formatDiffReport(report) }], details: report };
    },
  });

  pi.registerTool({
    name: "okf_init",
    label: "Initialize OKF Bundle",
    description: "Create missing OKF reserved files (`index.md`, `log.md`) without overwriting existing files.",
    promptSnippet: "Safely create an empty OKF bundle skeleton",
    promptGuidelines: [
      "Use okf_init only to create missing bundle scaffolding; it never authorizes inventing concept content or overwriting existing files.",
    ],
    parameters: Type.Object({
      path: Type.Optional(
        Type.String({
          description: "Bundle directory, relative to the current working directory. Defaults to okf.",
        }),
      ),
    }),
    async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
      const bundlePath = resolveFromCwd(ctx.cwd, params.path ?? "okf");
      const report = await withFileMutationQueue(join(bundlePath, "index.md"), () => initializeBundle(bundlePath));
      return { content: [{ type: "text", text: summarizeInit(report) }], details: report };
    },
  });

  pi.registerTool({
    name: "okf_validate",
    label: "Validate OKF Bundle",
    description:
      "Validate an Open Knowledge Format v0.2 bundle, including provenance, trust, lifecycle, and Attested Computation fields. Legacy v0.1 metadata is tolerated with migration warnings.",
    promptSnippet: "Validate an OKF bundle before reporting it complete",
    promptGuidelines: [
      "Use okf_validate after writing an OKF bundle. Resolve every conformance error; broken links and missing recommended metadata are warnings, not permission to invent content.",
    ],
    parameters: Type.Object({
      path: Type.Optional(
        Type.String({
          description: "Bundle directory, relative to the current working directory. Defaults to okf.",
        }),
      ),
    }),
    async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
      const report = await validateBundle(resolveFromCwd(ctx.cwd, params.path ?? "okf"));
      return {
        content: [{ type: "text", text: formatValidationReport(report) }],
        details: report,
      };
    },
  });

  pi.registerTool({
    name: "okf_capture",
    label: "Capture OKF Session",
    description:
      "Append durable decisions, changes, and open questions to the OKF bundle's log.md when they do not belong in a concept file.",
    promptSnippet: "Append a dated log entry when concepts are not the right place",
    promptGuidelines: [
      "Prefer updating concept files and indexes for durable product knowledge. Use okf_capture only for standing decisions, open questions, or history that should stay in log.md.",
      "Pass a short title, a one-line summary, and bullets for decisions, changes, and open questions. Do not include secrets or unsupported assumptions.",
    ],
    parameters: Type.Object({
      title: Type.Optional(Type.String({ description: "Short title for this session capture." })),
      summary: Type.String({ description: "Concise summary of the session's important outcome." }),
      decisions: Type.Optional(Type.Array(Type.String(), { description: "Decisions explicitly made during the session." })),
      changes: Type.Optional(
        Type.Array(Type.String(), { description: "Meaningful implementation or workflow changes from the session." }),
      ),
      questions: Type.Optional(
        Type.Array(Type.String(), { description: "Important unresolved questions or follow-ups." }),
      ),
      path: Type.Optional(
        Type.String({
          description: "Bundle directory, relative to the current working directory. Defaults to okf.",
        }),
      ),
    }),
    async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
      const bundlePath = resolveFromCwd(ctx.cwd, params.path ?? "okf");
      const report = await withFileMutationQueue(join(bundlePath, "log.md"), () =>
        captureSession(bundlePath, {
          title: params.title,
          summary: params.summary,
          decisions: params.decisions,
          changes: params.changes,
          questions: params.questions,
        }),
      );
      return {
        content: [{ type: "text", text: formatCaptureReport(report) }],
        details: report,
      };
    },
  });

  pi.on("session_start", async (_event, ctx) => {
    const bundlePath = resolveFromCwd(ctx.cwd, "okf");
    if (await pathExists(bundlePath)) ctx.ui.setStatus("okf", "OKF bundle detected: /okf-validate");
  });

  pi.on("before_agent_start", (event) => {
    if (!OKF_PROMPT_PATTERN.test(event.prompt)) return;
    return {
      systemPrompt: `${event.systemPrompt}\n\nOKF workflow: fetch the current specification with okf_spec when authoring or upgrading. Inspect available product, schema, analytics, and dashboard sources first. Prefer concept files and indexes for durable knowledge; use log.md for history and open questions. Record unknown facts in /log.md under \"Questions for maintainers\"; never invent business rules, SQL, or dashboard behavior. Non-reserved concept files need YAML frontmatter and bundle-relative links. Use generated: { by, at } for authorship. Validate before declaring the bundle complete.`,
    };
  });
}

function splitArguments(args: string): string[] {
  return args.trim().split(/\s+/).filter(Boolean);
}

function firstArgument(args: string): string | undefined {
  return splitArguments(args)[0];
}

async function pathExists(path: string): Promise<boolean> {
  try {
    await access(path);
    return true;
  } catch {
    return false;
  }
}
